{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, the highest-transfer analogue sharing dimethoxyaryl and tertiary amine motifs, has an absolute oral bioavailability of 34% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, which contains the same dimethoxy-tetrahydroisoquinoline core as the query, has an absolute oral bioavailability of approximately 49% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a structurally related dimethoxy-isoquinoline alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a dimethoxyphenyl basic amine drug, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Alfentanil, a moderately transferred basic drug, has an absolute oral bioavailability of about 42%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, despite lower structural similarity, shows oral bioavailability of 42–71% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "One verapamil study reported oral bioavailability of 18–20% in normal subjects, below the 20% threshold, indicating a possible borderline first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%) because multiple high-transfer analogues with shared dimethoxyaryl, tertiary amine, and isoquinoline features show absolute oral bioavailability mostly 22–49% in humans; the single sub-20% verapamil record is borderline and outweighed by verapamil's own absolute F values and other analogues.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule itself.",
    "Exact first-pass metabolism and transporter involvement for the lactam/tetrahydroisoquinoline scaffold are not directly characterized.",
    "Most evidence comes from drugs with different metabolic soft spots, so the precise F margin above 20% remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

